import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('unknown book is refused and null', async () => {
  const h = await createHost();
  assert.equal(await h.book('x'), null);
  for (const c of ['lend', 'giveBack', 'retire'] as const) {
    assert.equal((await h[c]('x')).ok, false);
  }
  assert.equal(await h.book('x'), null);
});

test('add, duplicate add refused', async () => {
  const h = await createHost();
  assert.deepEqual(await h.add('a'), { ok: true });
  assert.deepEqual(await h.book('a'), { status: 'available', loans: 0 });
  const r = await h.add('a');
  assert.equal(r.ok, false);
  assert.equal(typeof (r as { reason: string }).reason, 'string');
});

test('lend / giveBack cycle, max 3 loans', async () => {
  const h = await createHost();
  await h.add('a');
  for (let i = 1; i <= 3; i++) {
    assert.equal((await h.lend('a')).ok, true);
    assert.equal((await h.lend('a')).ok, false);
    assert.deepEqual(await h.book('a'), { status: 'lent', loans: i });
    assert.equal((await h.giveBack('a')).ok, true);
    assert.equal((await h.giveBack('a')).ok, false);
  }
  assert.equal((await h.lend('a')).ok, false);
  assert.deepEqual(await h.book('a'), { status: 'available', loans: 3 });
});

test('retire only when available, then frozen', async () => {
  const h = await createHost();
  await h.add('a');
  await h.lend('a');
  assert.equal((await h.retire('a')).ok, false);
  await h.giveBack('a');
  assert.equal((await h.retire('a')).ok, true);
  for (const c of ['add', 'lend', 'giveBack', 'retire'] as const) {
    assert.equal((await h[c]('a')).ok, false);
  }
  assert.deepEqual(await h.book('a'), { status: 'retired', loans: 1 });
});

test('fresh systems are independent; views are copies', async () => {
  const h1 = await createHost();
  const h2 = await createHost();
  await h1.add('a');
  assert.equal(await h2.book('a'), null);
  const v = await h1.book('a');
  v!.loans = 99;
  assert.equal((await h1.book('a'))!.loans, 0);
});

