'use strict';
// SAM v2 strict-profile spec of src/host.impl.ts (the stateful core: the books map).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_LOANS = 3;
const INITIAL_STATE = { books: {} };
const IDS = [{ book: 'a' }, { book: 'b' }];
const schema = { book: { type: 'string' } };
const intent = { action: (data = {}) => ({ ...data }), schema, domain: IDS };

const has = (model, id) => Object.prototype.hasOwnProperty.call(model.books, id);

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      books: { type: 'object' },
    },
    actions: {
      ADD: intent,
      LEND: intent,
      GIVE_BACK: intent,
      RETIRE: intent,
    },
    acceptors: {
      ADD: (model) => (p, { reject, next }) => {
        if (has(model, p.book)) return reject('book already exists');
        next.books = { ...model.books, [p.book]: { status: 'available', loans: 0 } };
      },
      LEND: (model) => (p, { reject, next }) => {
        if (!has(model, p.book)) return reject('no such book');
        const b = model.books[p.book];
        if (b.status !== 'available') return reject(`book is ${b.status}`);
        if (b.loans >= MAX_LOANS) return reject('book has reached its loan limit');
        next.books = { ...model.books, [p.book]: { status: 'lent', loans: b.loans + 1 } };
      },
      GIVE_BACK: (model) => (p, { reject, next }) => {
        if (!has(model, p.book)) return reject('no such book');
        const b = model.books[p.book];
        if (b.status !== 'lent') return reject(`book is ${b.status}`);
        next.books = { ...model.books, [p.book]: { status: 'available', loans: b.loans } };
      },
      RETIRE: (model) => (p, { reject, next }) => {
        if (!has(model, p.book)) return reject('no such book');
        const b = model.books[p.book];
        if (b.status !== 'available') return reject(`book is ${b.status}`);
        next.books = { ...model.books, [p.book]: { status: 'retired', loans: b.loans } };
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  ADD: (data = {}) => intents.ADD(data),
  LEND: (data = {}) => intents.LEND(data),
  GIVE_BACK: (data = {}) => intents.GIVE_BACK(data),
  RETIRE: (data = {}) => intents.RETIRE(data),
};

module.exports = { instance, init, actions, getState, setState };

