// Rules the brief requires, as invariants over spec/books.spec.cjs.
const MAX_LOANS = 3;
const STATUSES = ['available', 'lent', 'retired'];
const entries = (s) => Object.entries(s.books);
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

export const stateInvariants = [
  { name: 'status-is-known', pred: (s) => entries(s).every(([, b]) => STATUSES.includes(b.status)) },
  { name: 'loans-within-0..3', pred: (s) => entries(s).every(([, b]) => Number.isInteger(b.loans) && b.loans >= 0 && b.loans <= MAX_LOANS) },
  // a lent book has been lent at least once
  { name: 'lent-implies-a-loan', pred: (s) => entries(s).every(([, b]) => b.status !== 'lent' || b.loans >= 1) },
];

export const transitionInvariants = [
  // books are never removed, and loans never decrease
  {
    name: 'books-persist-and-loans-monotone',
    pred: (pre, _a, _d, post) => Object.keys(pre.books).every((id) => id in post.books && post.books[id].loans >= pre.books[id].loans),
  },
  // a step only touches the book it names
  {
    name: 'only-named-book-changes',
    pred: (pre, _a, d, post) => [...new Set([...Object.keys(pre.books), ...Object.keys(post.books)])]
      .every((id) => id === d.book || same(pre.books[id], post.books[id])),
  },
  // a retired book never changes again (never lent again)
  { name: 'retired-is-final', pred: (pre, _a, d, post) => pre.books[d.book]?.status !== 'retired' || same(pre.books[d.book], post.books[d.book]) },
  // one borrower at a time: a lent book cannot be lent again before it is given back
  { name: 'no-double-lend', pred: (pre, a, d, post) => !(a === 'LEND' && pre.books[d.book]?.status === 'lent') || same(pre, post) },
  // loans go up exactly when a book is lent, by exactly 1
  {
    name: 'loan-counted-on-lend',
    pred: (pre, a, d, post) => {
      const before = pre.books[d.book]?.loans ?? 0;
      const after = post.books[d.book]?.loans ?? 0;
      return a === 'LEND' && post.books[d.book]?.status === 'lent' && pre.books[d.book]?.status === 'available'
        ? after === before + 1
        : after === before;
    },
  },
];

export const rejectionInvariants = [
  { name: 'unknown-book-refused', pred: (s, a, d, v) => a === 'ADD' || d.book in s.books || v.rejected },
  { name: 'duplicate-add-refused', pred: (s, a, d, v) => a !== 'ADD' || !(d.book in s.books) || v.rejected },
  { name: 'fourth-loan-refused', pred: (s, a, d, v) => a !== 'LEND' || s.books[d.book]?.loans !== MAX_LOANS || v.rejected },
  { name: 'retired-refuses-everything', pred: (s, _a, d, v) => s.books[d.book]?.status !== 'retired' || v.rejected },
];

export default { stateInvariants, transitionInvariants, rejectionInvariants };

